# Mansion Calcinada 2F (C7, contract 53), 24 x 18. Arrival from 1F at (3,4) with the statues ON: the fossil amber's nook (south-west, behind the A door (3,10)) is open; the B door (7,5) shuts the way to the hall while they are ON, so
# the statue (5,7) of the arrival room must be thrown (OFF) after the Ambar fosil is taken. A burglar and a scientist, the third diary, the stairs up in the east room (20,3).
@map mansion_calcinada_2
@size 24 18
@interior yes
@area mansion_calcinada
@bg 0
@fill burnt_00
@flag mansion_sw 860      # the statues' switch: ONE flag for the whole mansion, every statue toggles it (set = "on"); the A doors are shut while it is clear, the B doors while it is set
@encounters grass rate=12
  cindermeer 36 40 25
  cindibex 36 40 20
  origamorph 36 40 15
  slickslime 36 39 15
  smogkeg 36 40 15
  tarbog 38 41 10
  foldling 36 40 10
@end
@spawn down 3 4 S
@spawn up 20 4 S
@legend
  .  tile=air_0
  a  tile=none object=charwall
  b  tile=burnt_01
  c  tile=burnt_11
  d  tile=burnt_00
  e  tile=burnt_10
  f  tile=ember_11
  g  tile=ember_01
  h  tile=burnt_10 object=rubble_c7
  i  tile=ember_00
  j  tile=ember_10
  k  tile=burnt_11 door=stairs
  l  tile=burnt_01 door=stairs
  m  tile=burnt_11 face=S gate=yes id=db npc=bdoor show_flag=mansion_sw text=mansion.door
  n  tile=burnt_11 object=bookshelf interact=look script=diary3
  o  tile=burnt_11 face=S id=s2 npc=statue_off script=statue
  p  tile=burnt_01 after=tr.ladron_m2a.after face=SW id=t1 npc=ladron_s range=4 text=tr.ladron_m2a.pre trainer=ladron_m2a
  q  tile=burnt_10 after=tr.cientifico_m2b.after face=NW id=t2 npc=cientifico_s range=3 text=tr.cientifico_m2b.pre trainer=cientifico_m2b
  r  tile=burnt_10 face=S gate=yes hide_flag=mansion_sw id=da npc=bdoor text=mansion.door
  s  tile=burnt_01 object=crate_plain
  t  tile=burnt_00 item=ambar_fosil
  u  tile=burnt_10 object=crate_plain
  v  tile=burnt_00 object=rubble_c7
  w  tile=burnt_11 item=prime_salve
  x  tile=burnt_01 item=growth_seed
@grid
  ........................
  ........................
  ..aaaa..aaaaaaaa..aaaa..
  .abkbc.abcbcbcbc.abclc..
  .adedhaadhdededhaadede..
  .abcbcbmbcbcbcbcbcbcbc..
  .adede.adededede.adede..
  .abnbo.abcbcpcbc.abcbc..
  .adede.adededede.adedq..
  ..ac...abcgfgfbc........
  ..araa.adeijijde..aaaa..
  .abcbc.abcgfgfbc.abcbc..
  .adede.adedededeaadhde..
  .ascbc.abfgfbcbcbcbcbc..
  .adete.aduijdeve.adede..
  .abcbc.abcbcbcxc.abcbw..
  ........................
  ........................
@warp k -> mansion_calcinada_1 spawn=up
@warp l -> mansion_calcinada_3 spawn=from2
# A statue switch: every one of them toggles the SAME flag (mansion_sw): the A doors (boarded while it is clear) open, the B doors (boarded while it is set) shut, or the other way round.
@script statue npc
    sfx hit
    jf mansion_sw off
    setf mansion_sw
    say mansion.sw.on
    end
  off:
    clrf mansion_sw
    say mansion.sw.off
@end
@script diary3 interact
    say mansion.d3
@end
